function timesTable(n) {
  const out = [];
  for (let i = 1; i <= 12; i++) out.push(`${n} x ${i} = ${n * i}`);
  return out;
}

function countVowels(text) {
  let n = 0;
  for (const ch of text.toLowerCase()) if ("aeiou".includes(ch)) n++;
  return n;
}
